class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        ones = s.count('1')
        best_gain = 0

        runs = []
        i = 0
        n = len(s)

        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            runs.append((s[i], j - i))
            i = j

        for k, (ch, length) in enumerate(runs):
            if ch == '1' and k > 0 and k + 1 < len(runs):
                if runs[k - 1][0] == '0' and runs[k + 1][0] == '0':
                    best_gain = max(best_gain, runs[k - 1][1] + runs[k + 1][1])

        return ones + best_gain
